require ROOT.'/includes/panel.php';?><div class="toolbar"><h1><?=$ticket?'Chamado #'.$id:'Central de suporte'?></h1><a class="outline btn" href="<?=e(url($prefix.'suporte.php?novo=1'))?>">+ Novo chamado</a></div><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;if($ticket):?><h2><?=e($ticket['subject'])?></h2><p class="muted"><?=e($ticket['customer'])?> • <?=e($ticket['status'])?></p><?php foreach(rows('SELECT m.*,u.name,u.role FROM messages m JOIN users u ON u.id=m.user_id WHERE ticket_id=? ORDER BY m.id',[$id]) as $m):?><article class="card <?=$m['role']==='admin'?'message-admin':''?>"><b><?=e($m['name'])?> <?=$m['role']==='admin'?' / Equipe':''?></b><small class="muted"> • <?=e($m['created_at'])?></small><p><?=e($m['body'])?></p></article><?php endforeach;foreach(rows('SELECT id,name FROM files WHERE ticket_id=? ORDER BY id',[$id]) as $f):?><p><a class="textlink" href="<?=e(url('baixar.php?id='.$f['id']))?>">↓ <?=e($f['name'])?></a></p><?php endforeach;endif;
