<div class="table-wrap"><table><tr><th>Chamado</th><th>Cliente</th><th>Status</th><th>Atualizado</th></tr><?php $ts=$admin?rows('SELECT t.*,u.name FROM tickets t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 200'):rows('SELECT t.*,u.name FROM tickets t JOIN users u ON u.id=t.user_id WHERE t.user_id=? ORDER BY t.id DESC LIMIT 200',[$u['id']]);foreach($ts as $t):?><tr><td><a href="<?=e(url($prefix.'suporte.php?id='.$t['id']))?>">#<?=$t['id']?> <?=e($t['subject'])?></a></td><td><?=e($t['name'])?></td><td><?=e($t['status'])?></td><td><?=e($t['updated_at'])?></td></tr><?php endforeach;?></table></div><?php endif;require ROOT.'/includes/endpanel.php';?>
